import {validatePatchGraph,type GraphNode,type GraphEdge,type GraphEndpoint} from '@/components/nyc-tron/ui/components/forge/graph/model';
export interface NodeGraphPolicy {readonly allowCycles?:boolean;readonly multipleInputs?:boolean}
export function validateMotionNodeGraph(nodes:readonly GraphNode[],edges:readonly GraphEdge[],policy:NodeGraphPolicy={}):void {
 if(policy.allowCycles!==undefined&&typeof policy.allowCycles!=='boolean'||policy.multipleInputs!==undefined&&typeof policy.multipleInputs!=='boolean')throw new TypeError('Invalid graph connection policy');
 validatePatchGraph(nodes,edges);const endpoints=new Set<string>(),inputs=new Set<string>(),byId=new Map(nodes.map(n=>[n.id,n]));
 for(const n of nodes){if(n.x<0||n.y<0||n.x+(n.width??200)>100000||n.y+58+Math.max(n.inputs.length,n.outputs.length)*44>100000)throw new RangeError('Node lies outside the bounded graph canvas');}
 const outgoing=new Map<string,string[]>(),indegree=new Map(nodes.map(n=>[n.id,0]));
 for(const e of edges){if(e.from.nodeId===e.to.nodeId)throw new TypeError('A node cannot connect to itself');const key=JSON.stringify([e.from.nodeId,e.from.portId,e.to.nodeId,e.to.portId]),input=JSON.stringify([e.to.nodeId,e.to.portId]);if(endpoints.has(key))throw new TypeError('This graph connection already exists');if(!policy.multipleInputs&&inputs.has(input))throw new TypeError('This input already has a connection');endpoints.add(key);inputs.add(input);const next=outgoing.get(e.from.nodeId)??[];next.push(e.to.nodeId);outgoing.set(e.from.nodeId,next);indegree.set(e.to.nodeId,indegree.get(e.to.nodeId)!+1);}
 if(!policy.allowCycles){const ready=nodes.filter(n=>indegree.get(n.id)===0).map(n=>n.id);let count=0;while(ready.length){const id=ready.pop()!;count++;for(const next of outgoing.get(id)??[]){indegree.set(next,indegree.get(next)!-1);if(indegree.get(next)===0)ready.push(next);}}if(count!==byId.size)throw new TypeError('This graph connection would create a cycle');}
}
export function validateMotionConnection(nodes:readonly GraphNode[],edges:readonly GraphEdge[],from:GraphEndpoint,to:GraphEndpoint,policy:NodeGraphPolicy={}):void {let id='proposed';const ids=new Set(edges.map(e=>e.id));while(ids.has(id))id+='-';validateMotionNodeGraph(nodes,[...edges,{id,from,to}],policy);}
export function motionGraphCanvasSize(nodes:readonly GraphNode[],width:number,height:number):{width:number;height:number} {if(![width,height].every(Number.isFinite)||width<120||height<100||width>4000||height>4000)throw new RangeError('Invalid graph viewport');return {width:Math.max(width,...nodes.map(n=>n.x+(n.width??200)+24)),height:Math.max(height,...nodes.map(n=>n.y+58+Math.max(n.inputs.length,n.outputs.length)*44+24))};}
